package com.astrawave.app.data

import com.astrawave.app.core.LibraryMediaType

/**
 * Search-facing mirror of the curated collection catalog used by Movies and TV.
 * Entries preserve the same ids, titles, descriptions, media types and query seeds so global
 * search can surface every current AstraWave collection without loading collection contents.
 */
data class AstraWaveCollectionSearchEntry(
    val id: String,
    val title: String,
    val subtitle: String,
    val mediaType: LibraryMediaType,
    val queries: List<String>,
)

